INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329415, 14047, 'The Guardian', 'en', 'Taiwan''s simulated internet blackout, explained', 'https://www.theguardian.com/global/video/2026/aug/14/taiwans-simulated-internet-blackout-explained-video', 'In Taipei on Thursday, the streets swiftly emptied into shelters as air raid sirens rang out and alerts pinged on mobile phones. These kinds of drills are the norm in cities across Taiwan, amid the growing threat posed by China across the strait. But this time, internet speeds were drastically cut, simulating a coordinated attack for the first time. Rafqa Touma speaks to Yu-chen Li, Guardian researcher on China affairs, who was on the ground ‘Tiktok wouldn’t open at all’: Taiwan simulates an internet blackout, with an eye on China threat Continue reading...', 'https://i.guim.co.uk/img/media/50ba95caf7e073a6e371e9d555d7aff3a12efe87/660_0_6602_5284/master/6602.jpg?width=140&quality=85&auto=format&fit=max&s=d7c80e7d1af4726bd961a379dd053d76', '2026-08-14T08:22:58+00:00', '2026-08-14T14:58:22.010255'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
