INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (332252, 14047, 'South China Morning Post', 'en', 'Hong Kong garners 16,000 submissions from consultation for city’s first 5-year plan', 'https://www.scmp.com/news/hong-kong/hong-kong-economy/article/3364092/hong-kong-garners-16000-submissions-consultation-citys-first-5-year-plan', 'Hong Kong authorities received more than 16,000 public submissions for the city’s inaugural five-year plan by the close of its consultation on Friday, with an official noting general support for more focused integration into national development and the strategic cultivation of emerging sectors. Secretary for Constitutional and Mainland Affairs Janice Tse Siu-wa described the blueprint, which is set to be delivered next month, as “a milestone in public administration”, adding that it would...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/14/8f7f0470-a1e0-49e2-b2b2-eb8c79d21132_22f3c1a7.jpg?itok=ZGVNpM4o&v=1786707354', '2026-08-14T11:35:57+00:00', '2026-08-14T15:03:28.482373'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (332262, 14047, 'South China Morning Post', 'en', 'Investment scam cases in Hong Kong drop 15%, but losses remain high at HK$1.65b', 'https://www.scmp.com/news/hong-kong/law-and-crime/article/3364044/investment-scam-cases-hong-kong-drop-15-losses-remain-high-hk165b', 'Hong Kong recorded a 15 per cent drop in investment scam cases in the first half of this year, but losses remained high at HK$1.65 billion (US$210 million), with police warning of fraudsters posing as representatives of legitimate overseas firms to swindle investors. Senior Superintendent Fanny Kung Hing-fun said on Friday that some of these firms of purported overseas origins did not exist at all, or had records of fraudulent activity in other countries. “For some of them, even their purported...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/14/9104a4ca-68eb-446f-8b97-60b7aef5f5ca_3fb327a3.jpg?itok=ASVP4hNf&v=1786698621', '2026-08-14T09:05:53+00:00', '2026-08-14T15:03:28.614536'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (332263, 14047, 'South China Morning Post', 'en', 'Hong Kong raises economic forecast after best half-yearly performance in 5 years', 'https://www.scmp.com/news/hong-kong/hong-kong-economy/article/3364047/hong-kong-raises-2026-economic-forecast-after-strongest-first-half-nearly-5-years', 'Hong Kong has raised its full-year economic growth forecast for 2026 to a range of 3.5 to 4.5 per cent following a 4.3 per cent expansion in the second quarter, supported by buoyant external trade and resilient domestic demand. Releasing its half-yearly economic report on Friday, the government revised its 2026 growth forecast from the previous range of 2.5 to 3.5 per cent, citing a stronger-than-expected performance in the first half of the year and taking into account the near-term outlook. It...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/14/42157903-b169-4d3a-8acc-57d929d30764_29e43942.jpg?itok=ilW3SiSl&v=1786703875', '2026-08-14T08:59:57+00:00', '2026-08-14T15:03:28.628136'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (332281, 14047, 'South China Morning Post', 'en', 'Hong Kong to list first Shanghai free-trade zone bond to defend yuan hub status', 'https://www.scmp.com/business/banking-finance/article/3363995/hong-kong-list-first-shanghai-free-trade-zone-bond-defend-yuan-hub-status', 'Hong Kong is set to welcome its first Shanghai free-trade zone offshore bond, using the landmark listing to defend its status as the world’s pre-eminent offshore yuan hub, amid mounting competition from its mainland rival. Hong Kong Exchanges and Clearing (HKEX) announced on Thursday that Shanghai Electric Global Capital – a financing arm of power and industrial equipment manufacturer Shanghai Electric – would list a 1.5 billion yuan (US$222.4 million) green free-trade zone bond on August...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/14/36344f58-a858-4a92-846c-fe9a119dd43a_4c19ac0f.jpg?itok=KGlSJYdV&v=1786683148', '2026-08-14T04:52:38+00:00', '2026-08-14T15:03:28.854288'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (332284, 14047, 'South China Morning Post', 'en', 'China tests canal link to Southeast Asia; rocket failure concerns: SCMP’s 7 highlights', 'https://www.scmp.com/news/china/article/3363971/china-tests-canal-link-southeast-asia-rocket-failure-concerns-scmps-7-highlights', 'We have selected seven stories from this week’s news across Hong Kong, mainland China, the wider Asia region and beyond that resonated with our readers and shed light on topical issues. If you would like to see more of our reporting, please consider subscribing. 1. China completes milestone test of US$10.8 billion canal link to Southeast Asia Chinese authorities have conducted the first full transit test along a 134.2km (83.4-mile) canal megaproject linking a vast inland region with Southeast...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/14/13620aab-181e-4777-9151-3dba3ba16792_08f9c84f.jpg?itok=nPJDmCUo&v=1786673085', '2026-08-14T04:15:07+00:00', '2026-08-14T15:03:28.893242'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
