INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (334205, 14047, 'South China Morning Post', 'en', 'URA posts HK$338 million operating surplus after three years of losses', 'https://www.scmp.com/news/hong-kong/hong-kong-economy/article/3364109/ura-posts-hk338-million-operating-surplus-after-three-years-losses', 'Hong Kong’s Urban Renewal Authority (URA) has recorded an operating surplus of HK$338 million (US$43.3 million) for the 2025-26 financial year, after reporting three straight years of losses. At a banquet on Friday to mark the statutory body’s 25th anniversary, chairman Chow Chung-kong announced that the URA had returned to profit in the 2025-26 financial year, recording an operating surplus to fund ongoing urban renewal initiatives. That followed three consecutive financial years of losses....', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/14/5209b683-ddd2-4be1-ae02-921fd27d24cb_093e18ac.jpg?itok=BfXjZcxc&v=1786721907', '2026-08-14T15:40:27+00:00', '2026-08-14T17:23:24.509108'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
