INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (316885, 14048, 'South China Morning Post', 'en', 'Trump turns to economic pain as US bombings fail to sway Iran', 'https://www.scmp.com/news/world/middle-east/article/3363874/trump-turns-economic-pain-us-bombings-fail-sway-iran', 'The US military campaign against Iran has so far failed to force Tehran to capitulate. The Trump administration is betting once again that suffocating economic pressure will do the job. Facing a shortfall of necessary munitions and wary of continuing an unpopular war, Trump and his top officials are returning to a familiar playbook with Iran: relying on a steady increase in economic sanctions and a naval blockade to stifle oil exports. The renewed emphasis on economic pain – it was dubbed...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/13/b9f5b183-a922-4787-8b1d-f02338daf365_13b673b4.jpg?itok=T0tpTcAZ&v=1786601578', '2026-08-13T06:28:04+00:00', '2026-08-13T07:15:34.676663'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
