INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (315626, 14061, 'Aaj Tak', 'hi', 'टाटा ग्रुप में विवाद की पुरानी है कहानी, चंद्रशेखरन के इस्‍तीफे की Inside Story', 'https://www.aajtak.in/business/news/story/inside-story-of-tata-group-dispute-and-n-chandrasekaran-resign-tutd-dskc-2621109-2026-08-13', 'एन. चंद्रशेखरन ने बुधवार को टाटा संस के चेयरमैन पद से इस्‍तीफा दे दिया, जिसने टाटा ग्रुप में विवाद का एक नया चैप्‍टर खुल गया. आखिर चंद्रशेखरन ने अचानक से इस्‍तीफा क्‍यों दिया? एक दशक पहले भी कुछ ऐसा ही हुआ था... आइए जानते हैं इसकी इनसाइड स्‍टोरी.', '', '2026-08-13T05:44:30+00:00', '2026-08-13T06:16:38.375898'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
