INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (317392, 14062, 'The Commune', 'en', 'Funding Peaceful Protests Cannot Be “Undesirable Purpose” To Deny FCRA Renewal, Says Kerala High Court', 'https://thecommunemag.com/funding-peaceful-protests-cannot-be-undesirable-purpose-to-deny-fcra-renewal-says-kerala-high-court', 'The Kerala High Court has set aside the rejection of FCRA renewal applications of two NGOs after the Centre relied on a report of a Central Security Agency alleging that the organisations had funded protests against the Vizhinjam Port project, as reported in LiveLaw. The judgment was delivered by Justice Bechu Kurian Thomas while considering […] The post Funding Peaceful Protests Cannot Be “Undesirable Purpose” To Deny FCRA Renewal, Says Kerala High Court appeared first on The Commune .', '', '2026-08-13T07:09:19+00:00', '2026-08-13T08:13:22.392090'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
