INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (314841, 14067, 'Aaj Tak', 'hi', 'मॉनसून सत्र का आज आखिरी दिन, मकर द्वार के बाहर विपक्ष का प्रोटेस्ट', 'https://www.aajtak.in/india/news/story/parliament-monsoon-session-2026-live-updates-lok-sabha-rajya-sabha-proceedings-amit-shah-ntc-amkr-2621065-2026-08-13', 'Parliament Monsoon Session Live Updates: गुरुवार को संसद के मॉनसून सत्र का अंतिम दिन है. संसद परिसर में विरोध-प्रदर्शन देखने को मिल रहा है. एनडीए और विपक्षी दल लगातार प्रदर्शन कर रहे हैं और दोनों ओर से टकराव जारी है. नीट पेपर लीक और छात्रों के प्रदर्शन के दौरान कथित बल प्रयोग को लेकर संसद में सरकार और विपक्ष के बीच लगातार टकराव देखने को मिला है.', '', '2026-08-13T04:34:35+00:00', '2026-08-13T05:21:04.902181'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
